// ── Wallet Provider equips the Wallet Unit with WIA and key attestations ── Wallet Provider → Wallet Unit · step 1 in every flow
// rule: WP: MUST · "The wallet provider shall ensure that a wallet unit contains wallet instance attestations as needed for issuance of person identification data and electronic attestations of attributes." · "A wallet provider shall ensure that a wallet unit is in possession of key attestations as needed for issuance of person identification data and device-bound electronic attestations of attributes." · "A wallet provider shall verify the integrity of the wallet instance and sign or seal the wallet instance attestation."
/** JWS, produced by WP. */
export type WalletInstanceAttestation = {
  header: {
    typ: string // MUST · Marks the JWT as an OAuth client attestation (oauth-client-attestation+jwt). · "typ: REQUIRED. The JWT type MUST be oauth-client-attestation+jwt."
    alg: string // MUST · Algorithm the JWS is signed with (or the JWE key is managed with), e.g. ES256. [R1]
    x5c: string[] // MUST · Certificate chain of the Wallet Provider key that signs the WIA. · "used to validate the signature on the Wallet Attestation MUST be included in the x5c JOSE header of the Client Attestation JWT"
  }
  payload: {
    iss: string // MUST · The Wallet Provider that issued the attestation. · "iss: REQUIRED. The iss (issuer) claim MUST contains a unique identifier for the entity that issued the JWT."
    sub: string // MUST · The Wallet's client_id; must match the client_id in the request. · "The subject claim for the Wallet Attestation MUST be a value that is shared by all Wallet instances using the present type of wallet implementation."
    iat?: number // MAY · Time the JWT was issued, in seconds since the epoch. [R2]
    exp: number // MUST · Expiry of the WIA. · "the difference between the time when the wallet provider verified the integrity of the wallet instance and the time they will indicate in the 'exp' claim of the issued wallet instance attestation shall be less than 24 hours."
    cnf: { // MUST · Public key of the Wallet instance; the client attestation PoP is signed with the matching private key. · "cnf: REQUIRED. The cnf (confirmation) claim MUST specify a key conforming to [RFC7800] that is used by the Client Instance to generate the Client Attestation PoP JWT for client authentication with an authorization server. The key MUST be expressed using the "jwk" representation."
      jwk?: { // no rule · The holder's public key, as a JWK, that the JWT is bound to.
        kty: string // MUST · Key type of the JWK, e.g. EC for elliptic curve keys. [R3]
        crv: string // MUST · Elliptic curve of the key, e.g. P-256. [R4]
        x: string // MUST · x coordinate of the EC public key, base64url encoded. [R5]
        y: string // MUST · y coordinate of the EC public key, base64url encoded. [R6]
      }
    }
    wallet_name: string // MUST · Human-readable name of the Wallet solution. · "the 'wallet_name' claim specified in Appendix E of OID4VCI, where its value shall be the identifier of the wallet solution that can be found on the list of wallet providers"
    wallet_link?: string // SHOULD · URL with further information about the Wallet and the Wallet Provider. · "A wallet instance attestation should also include the 'wallet_link' claim specified in Appendix E of OID4VCI and the value of this claim shall be a URI where further information about the wallet solution can be obtained."
    wallet_version: string // MUST · Version of the Wallet solution. · "a 'wallet_version' claim (4), that shall be a string whose value shall be the version of the wallet solution."
    wallet_solution_certification_information: { // MUST · Information about the conformity assessment body that certified the Wallet solution. · "a 'wallet_solution_certification_information' claim, that shall be a JSON object containing information about the conformity assessment body that certified the wallet solution"
      conformity_assessment_body?: string // no rule · The individual members describing the certification of the Wallet solution.
      certification_number?: string // no rule
    }
    client_status: { // MUST ⚠ · Revocation status of the Wallet instance: a status list reference and how long it is maintained. · "it shall maintain the revocation status of the relevant wallet instance until the 'wallet_instance_status.exp' indicated in that wallet instance attestation has passed." · "EAA-6.2.10.1-15: The wallet provider shall implement the attestation revocation mechanisms specified in EAA-6.2.10.1-02 in their wallet solution."
      status: { // MUST · Status list reference for the Wallet instance's revocation status. · "The wallet provider shall use the attestation status list mechanism (EAA-6.2.10.1-02.2) for the revocation of a wallet instance attestation (WIA)."
        status_list?: { // auth-code-par, pre-auth: Issuer: MUST when the status list mechanism is used | nested-presentation: Issuer: MUST in an SD-JWT VC with a status claim · Reference to a status list: which list (uri) and which position in it (idx). [R7] [R8] [R9]
          idx?: number // auth-code-par, pre-auth: Issuer: MUST for the PID, qualified EAA and EAA provided by or on behalf of a public sector body responsible for an authentic source | nested-presentation: Issuer: MUST · Index of this token's entry in the status list. [R10] [R11]
          uri?: string // auth-code-par, pre-auth: Issuer: MUST | nested-presentation: Issuer: MUST · URL where the Status List Token can be fetched. [R12] [R13]
        }
      }
      exp: number // MUST · Until when the Wallet Provider keeps maintaining that status entry. · "'exp': a NumericDate, as specified in RFC 7519, defining the time until which the wallet provider will maintain the revocation status at the status list index referenced in 'status'."
    }
  }
}

// ── Credential Offer ── Credential Issuer → Wallet Unit · step 2 in every flow
// rule: Issuer: MUST if issuer-initiated flows are supported; Wallet: MUST · "If Issuer-initiated flows are supported, they MUST use the Credential Offer as defined in Section 4.1 of [OIDF.OID4VCI]." · "Both Issuer and Wallet MUST support Credential Offer in both same-device and cross-device flows."
export interface Offer {
  query: {
    credential_offer?: { // except pre-auth: MAY · The Credential Offer itself, passed by value as URL-encoded JSON. · "credential_offer: Object with the Credential Offer parameters. This MUST NOT be present when the credential_offer_uri parameter is present."
      credential_issuer: string // except pre-auth: MUST · Identifier (URL) of the Credential Issuer; the Wallet uses it to fetch the issuer metadata. [R14]
      credential_configuration_ids: string[] // except pre-auth: MUST · Which credentials are offered, as keys into credential_configurations_supported in the issuer metadata. [R15]
      grants: { // except pre-auth: MUST · Grant types the Wallet can use to obtain an access token for this offer, with their parameters. [R16]
        authorization_code: { // except pre-auth: MUST · Parameters for starting issuance with the authorization code flow. [R17]
          issuer_state?: string // except pre-auth: MAY · Opaque value the Wallet passes back in the authorization request so the issuer can link it to this offer. [R18]
        }
      }
    }
    credential_offer_uri?: string // only pre-auth: MAY · URL where the Wallet fetches the Credential Offer, instead of receiving it inline. · "credential_offer_uri: String that is a URL using the https scheme referencing a resource containing a JSON object with the Credential Offer parameters. This MUST NOT be present when the credential_offer parameter is present."
  }
  body: {
    credential_issuer: string // except pre-auth: MUST [R14]
    credential_configuration_ids: string[] // except pre-auth: MUST [R15]
    grants: { // except pre-auth: MUST [R16]
      authorization_code: { // except pre-auth: MUST [R17]
        issuer_state?: string // except pre-auth: MAY [R18]
      }
    }
  }
}
// also:
//   - URL scheme that invokes the Wallet: Issuer: MAY · Custom URL scheme that makes the device open a Wallet with the Credential Offer. · "The d-you wallet is invoked with the openid-credential-offer:// scheme of OpenID4VCI, for an offer by value (authorization code flow) and by reference (pre-authorized code flow)."

// ── Credential Issuer metadata ── GET /.well-known/openid-credential-issuer · Wallet Unit → Credential Issuer · steps auth-code-par 3, nested-presentation 3, pre-auth 5
