        keys: { // MUST [R21]
          kty: string // MUST [R21]
          crv: string // MUST [R21]
          x: string // MUST [R21]
          y: string // MUST [R21]
          use: string // MUST [R21]
          kid: string // MUST [R21]
          alg: string // MUST [R21]
        }[]
